export function cookiesPageHTML(){return `<section class="wrap cookie-information"><h1>Cookies и настройки браузера</h1><p>Сайт «Оптика Имидж» использует хранилище браузера, чтобы сохранять ваш выбор и обеспечивать работу сайта.</p><h2>Что сохраняется в браузере</h2><ul><li>Корзина: выбранные модели и их количество.</li><li>Избранное: модели, отмеченные сердечком.</li><li>Отметка о просмотре этого уведомления и показе вступительной анимации.</li><li>При входе в административную часть — данные сеанса входа. Срок сохранения зависит от выбора «Запомнить меня».</li></ul><p>Корзина и избранное сохраняются в localStorage. Отдельные настройки текущего сеанса сохраняются в sessionStorage. Это технологии хранения браузера; их назначение описано здесь вместе с cookies.</p><h2>Внешняя карта</h2><p>Встроенная Яндекс Карта загружается только после нажатия «Загрузить Яндекс Карту». При этом браузер устанавливает соединение с Яндексом: сервис получает технические данные, в том числе IP-адрес, и может использовать собственные cookies. <a href="https://yandex.ru/legal/cookies_policy/ru/" target="_blank" rel="noopener noreferrer">Правила использования cookies Яндекса</a>.</p><h2>Как управлять сохранёнными данными</h2><p>Удалить cookies и данные сайта можно в настройках браузера. После удаления данных корзина, избранное и сохранённый вход могут сброситься. Встроенную карту можно не загружать: адрес и телефон салона доступны без неё.</p><p>Это описание работы браузерного хранилища. Согласие на обработку имени, телефона и данных заказа запрашивается отдельно в форме заказа.</p><a class="button" href="/">На главную</a></section>`;}
export function installCookieNotice(){
 const key='imidzh-optika:cookie-notice:v1';let seen=false;try{seen=localStorage.getItem(key)==='seen';}catch{}
 if(!seen){const notice=document.createElement('aside');notice.className='cookie-notice';notice.setAttribute('aria-label','Cookies и данные браузера');notice.innerHTML='<p>Мы используем хранилище браузера для корзины, избранного и настроек сайта. Внешняя Яндекс Карта загружается по вашему запросу. <a href="/cookies">Подробнее</a></p><button type="button" class="button" data-cookie-dismiss>Понятно</button>';document.body.append(notice);notice.querySelector('button').addEventListener('click',()=>{try{localStorage.setItem(key,'seen');}catch{}notice.remove();});}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-load-map]');if(!button)return;const frame=document.createElement('iframe');frame.title='Яндекс Карта — Оптика Имидж, Лермонтовский проспект, 19 корпус 1';frame.src='https://yandex.ru/map-widget/v1/?ol=biz&oid=1207435686&z=17';frame.width='700';frame.height='560';frame.allowFullscreen=true;frame.referrerPolicy='no-referrer';button.closest('.map-choice').replaceWith(frame);});
}
